import React, { useEffect } from "react";
import axios from "axios";
import { useNavigate } from "react-router-dom";

const PaymentPending = () => {
  const navigate = useNavigate();

  useEffect(() => {
    const orderId = localStorage.getItem("latestOrderId");

    if (!orderId) {
      navigate("/checkout");
      return;
    }

    const interval = setInterval(async () => {
      try {
        const res = await axios.get(`http://localhost:5000/order-status/${orderId}`);

        if (res.data.paymentStatus === "approved") {
          clearInterval(interval);
          alert("Payment Successful ✅");
          navigate("/order-success");
        }

        if (res.data.paymentStatus === "rejected") {
          clearInterval(interval);

          // reopen payment window on checkout
          localStorage.setItem("retryPayment", "true");

          alert("Payment not received ❌ Please try again");
          navigate("/checkout");
        }
      } catch (err) {
        console.log("Status check error:", err);
      }
    }, 5000);

    return () => clearInterval(interval);
  }, [navigate]);

  return (
    <div style={container}>
      <div style={card}>
        <h2 style={heading}>Payment Under Verification ⏳</h2>
        <p style={text}>We are checking your payment.</p>
        <p style={text}>Please wait for admin approval.</p>
      </div>
    </div>
  );
};

const container = {
  display: "flex",
  justifyContent: "center",
  alignItems: "center",
  minHeight: "70vh",
};

const card = {
  background: "#fff",
  padding: "40px",
  borderRadius: "20px",
  boxShadow: "0 8px 20px rgba(0,0,0,0.08)",
  textAlign: "center",
  width: "420px",
};

const heading = {
  color: "#ff4f87",
  marginBottom: "15px",
};

const text = {
  color: "#555",
  fontSize: "16px",
  margin: "8px 0",
};

export default PaymentPending;
